//! Target owner/content index publication shares the actual import admission.
use super::*;
#[test]
fn inert_template_import_owner_indexes_payload_copy_refusal_and_recovery_are_atomic(){
 let mut doc=crate::html::parse("<html><body></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);assert_eq!(page.console_eval(&mut doc,&mut forms,"var source=document.createElement('template');source.innerHTML='<span>held</span><template><b>nested</b></template>';var original=source.content,nested=original.lastChild.content;").errors,0);let Value::Host(source)=page.runtime.execute("source",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("source")};page.begin_job();let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};let Value::Host(target)=b.create_xml_document(MAIN_IMPLEMENTATION,&[Value::Null,Value::String(String::new())]).unwrap()else{panic!("target")};b.state.node_limit=b.doc.nodes.len();let before=(b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.inert_documents.template_documents.len(),b.state.inert_documents.template_contents.len(),b.doc.nodes.len());let limit=b.state.retained_limit;let copies=b.state.copy_work;
 for storage in [true,false]{if storage{b.state.retained_limit=before.0;}else{b.state.copy_work=0;}assert!(b.import_into_inert_document(target,source,true).is_err());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.inert_documents.template_documents.len(),b.state.inert_documents.template_contents.len(),b.doc.nodes.len()),before);assert!(!b.state.inert_documents.template_documents.contains_key(&target));b.state.retained_limit=limit;b.state.copy_work=copies;}
 let Value::Host(copy)=b.import_into_inert_document(target,source,true).unwrap()else{panic!("copy")};assert!(copy>=FIRST_ENTRY);assert_eq!(b.state.inert_documents.node(copy).unwrap().owner,target);let owner=*b.state.inert_documents.template_documents.get(&target).unwrap();assert!(matches!(b.state.inert_documents.node(owner).unwrap().kind,Kind::TemplateDocument{kind:crate::html::DocumentKind::Xml,..}));let content=*b.state.inert_documents.template_contents.get(&copy).unwrap();assert_eq!(b.state.inert_documents.node(content).unwrap().owner,owner);let links=b.state.inert_documents.entries[before.2..].iter().map(|entry|match entry{Entry::Node(node)=>node.children.capacity()*size_of::<u32>()+match &node.kind{Kind::Element(s)=>s.capacity(),Kind::Text(s)=>s.capacity(),Kind::Doctype(d)=>d.capacity(),Kind::ProcessingInstruction{target,data}=>target.capacity()+data.capacity(),_=>0},Entry::Implementation=>0,_=>panic!("no-slot identities remain entries")}).sum::<usize>();let snapshots=b.state.inert_documents.generated[before.3..].iter().map(|source|node_bytes(&source.node)+size_of::<Node>()+2*size_of::<usize>()+match &source.node.kind{NodeKind::Element{tag,href,..}=>tag.capacity()+href.as_ref().map_or(0,String::capacity),_=>0}).sum::<usize>();assert_eq!(b.state.retained,before.0+links+snapshots+b.state.inert_documents.backing_bytes()-before.1);assert_eq!(b.doc.nodes.len(),before.6);
}
